// Regression test for the Task #460 replay portal-classification logic.
//
// The broken batch we are replaying was generated by code that
// hardcoded `/portal/*` in CTAs even for Room30 buyers and never
// stamped `metadata.portalKey`. The replay script must NOT infer the
// portal from those legacy CTA paths - it must default to `room30` so
// the resend lands on `/members/sign-up`.
//
// Run with: node --experimental-strip-types --test src/resend-broken-account-emails.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { inferPortalKey } from "./resend-broken-account-emails-helpers.ts";

describe("inferPortalKey (Task #460 replay)", () => {
  it("defaults a legacy row with /portal/sign-up CTA and no portalKey to room30", () => {
    assert.equal(
      inferPortalKey("https://abc.riker.replit.dev/portal/sign-up?...", null),
      "room30",
    );
    assert.equal(
      inferPortalKey("https://abc.riker.replit.dev/portal/sign-in?...", {}),
      "room30",
    );
  });

  it("respects an explicit metadata.portalKey=main even when CTA path looks like /members/", () => {
    assert.equal(
      inferPortalKey("https://room30.ai/members/sign-up", { portalKey: "main" }),
      "main",
    );
  });

  it("respects an explicit metadata.portalKey=room30", () => {
    assert.equal(
      inferPortalKey("https://room30.ai/portal/sign-up", { portalKey: "room30" }),
      "room30",
    );
  });

  it("ignores garbage portalKey values and falls back to room30", () => {
    assert.equal(
      inferPortalKey("https://room30.ai/portal/sign-up", { portalKey: "nonsense" }),
      "room30",
    );
  });

  it("never returns main when metadata.portalKey is missing, regardless of CTA", () => {
    const cases = [
      "https://room30.ai/portal/sign-up",
      "https://room30.ai/portal/sign-in",
      "https://abc.replit.dev/portal/sign-up",
      "",
    ];
    for (const cta of cases) {
      assert.equal(inferPortalKey(cta, null), "room30", `cta=${cta}`);
      assert.equal(inferPortalKey(cta, {}), "room30", `cta=${cta}`);
    }
  });
});
